def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    background = max(range(10), key=lambda c: sum(row.count(c) for row in grid))

    full_colors = {row[0] for row in grid if all(v == row[0] for v in row)}
    for row in grid:
        color = row[0]
        if color == background or color not in full_colors:
            continue
        k = 0
        while k < w and row[k] == color:
            k += 1
        if 0 < k < w and all(v == background for v in row[k:]):
            for j in range(k, w):
                out[grid.index(row)][j] = 1
    return out
